{"content": """"Audit which contacts of the "Crie Seu Site" list were ever invited to the SEBRAE workshop.

For each contact: open the chat, walk its history to the oldest message, and collect every
message that mentions SEBRAE / Inicia.IA / oficina, with the message's own timestamp.
"""
import json
import re
import sys
import time

import cdp

PATTERN = re.compile(r"sebrae|inicia\.?\s*ia|oficina", re.I)

JS = r"""
(async (LAST5) => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const inp = [...document.querySelectorAll('input[type="text"]')].find(i => i.offsetParent !== null);
  if (!inp) return JSON.stringify({error: 'no search input'});
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  inp.focus(); setter.call(inp, ''); inp.dispatchEvent(new Event('input', {bubbles: true}));
  await sleep(200);
  setter.call(inp, LAST5); inp.dispatchEvent(new Event('input', {bubbles: true}));
  await sleep(1100);
  const row = document.querySelector('#pane-side [role="gridcell"]');
  if (!row) return JSON.stringify({error: 'row not found'});
  const rowTitle = row.querySelector('[data-testid="cell-frame-title"] span[title]')?.getAttribute('title') || '';
  const rc = row.getBoundingClientRect();
  const el = document.elementFromPoint(rc.left + 60, rc.top + rc.height / 2) || row;
  const base = {bubbles: true, cancelable: true, view: window, clientX: rc.left + 60, clientY: rc.top + rc.height / 2, button: 0};
  el.dispatchEvent(new PointerEvent('pointerdown', {...base, pointerId: 1, pointerType: 'mouse', isPrimary: true, buttons: 1}));
  el.dispatchEvent(new MouseEvent('mousedown', {...base, buttons: 1}));
  el.dispatchEvent(new PointerEvent('pointerup', {...base, pointerId: 1, pointerType: 'mouse', isPrimary: true, buttons: 0}));
  el.dispatchEvent(new MouseEvent('mouseup', {...base, buttons: 0}));
  el.dispatchEvent(new MouseEvent('click', {...base, buttons: 0}));
  await sleep(1300);
  const hdrFull = document.querySelector('#main header')?.innerText || '';
  const norm = s => (s || '').replace(/\s+/g, ' ').trim().toLowerCase();
  const okHdr = hdrFull.replace(/\D/g, '').includes(LAST5) || (rowTitle && norm(hdrFull).includes(norm(rowTitle)));
  if (!okHdr) return JSON.stringify({error: 'header mismatch', rowTitle, hdr: hdrFull.slice(0, 40)});

  const pane = document.querySelector('[data-testid="conversation-panel-messages"]');
  if (!pane) return JSON.stringify({error: 'no message pane'});
  const seen = {};
  const grab = () => {
    for (const m of document.querySelectorAll('#main [data-testid="msg-container"]')) {
      const meta = m.querySelector('[data-pre-plain-text]')?.getAttribute('data-pre-plain-text') || '';
      const body = (m.innerText || '').replace(/\n/g, ' ').trim();
      seen[meta + '|' + body.slice(0, 60)] = {meta, body: body.slice(0, 220)};
    }
  };
  grab();
  for (let i = 0; i < 30; i++) {
    const before = pane.scrollHeight;
    pane.scrollTop = 0;
    await sleep(800);
    const beforeCount = Object.keys(seen).length;
    grab();
    if (pane.scrollHeight === before && Object.keys(seen).length === beforeCount && i > 0) break;
  }
  return JSON.stringify({rowTitle, hdr: hdrFull.replace(/\n/g, ' ').slice(0, 40), msgs: Object.values(seen)});
})(%s)
"""


def main():
    targets = json.load(open(sys.argv[1], encoding="utf-8")) if len(sys.argv) > 1 else []
    c = cdp.connect()
    out = []
    for t in targets:
        t0 = time.time()
        rec = {"id": t["id"], "name": t["n"], "last5": t["last5"]}
        try:
            data = json.loads(c.eval(JS % json.dumps(t["last5"])))
        except Exception as exc:  # noqa: BLE001
            data = {"error": f"{type(exc).__name__}: {str(exc)[:120]}"}
        if "error" in data:
            rec.update(data)
        else:
            hits = [m for m in data["msgs"] if PATTERN.search(m["body"])]
            rec["total_msgs"] = len(data["msgs"])
            rec["hdr"] = data.get("hdr")
            rec["hits"] = hits
        rec["secs"] = round(time.time() - t0, 1)
        out.append(rec)
        print(json.dumps({k: v for k, v in rec.items() if k != "hits"}, ensure_ascii=False)
              + f" hits={len(rec.get('hits', []))}", flush=True)
        for h in rec.get("hits", []):
            print("    ", h["meta"], "|", h["body"][:110].replace("\n", " "), flush=True)
    json.dump(out, open("sebrae_audit.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main()
