{"content": """"Who received yesterday's authorization request and still hasn't answered?

Opens every conversation that got the phase-1 ask, walks to the oldest message and separates
inbound messages (the contact's) from ours, using each bubble's own timestamp.
"""
import json
import re
import sys
import time

import cdp

META = re.compile(r"\[(\d{2}:\d{2}), (\d{2}/\d{2}/\d{4})\] ([^:]+):")

JS = r"""
(async (LAST5) => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const inp = [...document.querySelectorAll('input[type="text"]')].find(i => i.offsetParent !== null);
  if (!inp) return JSON.stringify({error: 'no search input'});
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  inp.focus(); setter.call(inp, ''); inp.dispatchEvent(new Event('input', {bubbles: true}));
  await sleep(300);
  setter.call(inp, LAST5); inp.dispatchEvent(new Event('input', {bubbles: true}));
  await sleep(1150);
  const row = document.querySelector('#pane-side [role="gridcell"]');
  if (!row) return JSON.stringify({error: 'row not found'});
  const rowTitle = row.querySelector('[data-testid="cell-frame-title"] span[title]')?.getAttribute('title') || '';
  inp.focus();
  inp.dispatchEvent(new KeyboardEvent('keydown', {key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true, cancelable: true}));
  await sleep(1500);
  const hdrFull = document.querySelector('#main header')?.innerText || '';
  const norm = s => (s || '').replace(/\s+/g, ' ').trim().toLowerCase();
  if (!(hdrFull.replace(/\D/g, '').includes(LAST5) || (rowTitle && norm(hdrFull).includes(norm(rowTitle)))))
    return JSON.stringify({error: 'header mismatch', rowTitle, hdr: hdrFull.slice(0, 40)});

  const pane = document.querySelector('[data-testid="conversation-panel-messages"]');
  const seen = {};
  const grab = () => {
    for (const m of document.querySelectorAll('#main [data-testid="msg-container"]')) {
      const meta = m.querySelector('[data-pre-plain-text]')?.getAttribute('data-pre-plain-text') || '';
      const body = (m.innerText || '').replace(/\n/g, ' ').trim();
      seen[meta + '|' + body.slice(0, 50)] = {meta, body: body.slice(0, 200)};
    }
  };
  grab();
  for (let i = 0; i < 25; i++) {
    const before = pane.scrollHeight, n = Object.keys(seen).length;
    pane.scrollTop = 0;
    await sleep(750);
    grab();
    if (pane.scrollHeight === before && Object.keys(seen).length === n && i > 0) break;
  }
  return JSON.stringify({rowTitle, msgs: Object.values(seen)});
})(%s)
"""


def main():
    targets = json.load(open(sys.argv[1], encoding="utf-8"))
    c = cdp.connect()
    out = []
    for t in targets:
        rec = {"id": t["id"], "name": t["n"], "status": t.get("st")}
        try:
            data = json.loads(c.eval(JS % json.dumps(t["last5"])))
        except Exception as exc:  # noqa: BLE001
            data = {"error": f"{type(exc).__name__}: {str(exc)[:120]}"}
        if "error" in data:
            rec["error"] = data["error"]
            rec["hdr"] = data.get("hdr")
        else:
            inbound = []
            for m in data["msgs"]:
                g = META.match(m["meta"])
                if not g:
                    continue
                hh, dd, who = g.group(1), g.group(2), g.group(3).strip()
                if who.lower().startswith(("comunicação acirv", "acirv", "você")):
                    continue
                inbound.append({"when": f"{dd} {hh}", "who": who, "body": m["body"]})
            # ordena por data+hora
            inbound.sort(key=lambda r: (r["when"][3:], r["when"][:5]))
            rec["inbound"] = inbound
            rec["last_inbound"] = inbound[-1] if inbound else None
        out.append(rec)
        li = rec.get("last_inbound")
        print(f"{rec['name'][:34]:34} {rec.get('status',''):18} "
              + ("SEM RESPOSTA" if not li else f"{li['when']} -> {li['body'][:70]}")
              + (f"  [{rec['error']}]" if rec.get("error") else ""), flush=True)
    json.dump(out, open("replies_audit.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)


if __name__ == "__main__":
    main()
