{"content": """"Lê as últimas mensagens de uma lista de conversas do WhatsApp Web via CDP.

Entrada: JSON com [{"key": "<sufixo do telefone ou nome>", "name": "rótulo"}]
Saída:   lista com header, existência de mensagem não lida e as últimas N bolhas
         (remetente, timestamp, direção, texto). Salva em convos_<tag>.json.
"""
import json
import sys
import time

import cdp

JS = r"""
(async (KEY, N) => {
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const inp = [...document.querySelectorAll('input[type="text"]')].find(i => i.offsetParent !== null);
  if (!inp) return JSON.stringify({error: 'no search input'});
  const setter = Object.getOwnPropertyDescriptor(window.HTMLInputElement.prototype, 'value').set;
  inp.focus(); setter.call(inp, ''); inp.dispatchEvent(new Event('input', {bubbles: true}));
  await sleep(280);
  setter.call(inp, KEY); inp.dispatchEvent(new Event('input', {bubbles: true}));
  await sleep(1150);
  const row = document.querySelector('#pane-side [role="row"]');
  const rowTitle = row?.querySelector('[data-testid="cell-frame-title"] span[title]')?.getAttribute('title') || '';
  inp.focus();
  inp.dispatchEvent(new KeyboardEvent('keydown', {key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true, cancelable: true}));
  await sleep(1600);
  const hdrEl = document.querySelector('#main header');
  const hdr = (hdrEl?.innerText || '').split(String.fromCharCode(10)).join(' ').slice(0, 60);
  if (!rowTitle && !hdr) return JSON.stringify({error: 'chat not found', key: KEY});

  const nodes = [...document.querySelectorAll('#main [data-testid="msg-container"]')];
  const msgs = [];
  for (const m of nodes.slice(-N)) {
    const meta = m.querySelector('[data-pre-plain-text]')?.getAttribute('data-pre-plain-text') || '';
    const tm = meta.match(/\[([^\]]+)\]/);
    const sender = meta.replace(/\[[^\]]*\]\s*/, '').replace(/:\s*$/, '');
    const body = (m.innerText || '').replace(/\n/g, ' ').trim();
    const isOut = /Comunica..o ACIRV|Acirv|Você|Eu$/i.test(sender) ||
                  !!m.querySelector('[data-testid="msg-dblcheck"], [data-icon="msg-dblcheck"]');
    const media = [...m.querySelectorAll('img[alt], [data-testid="media-container"]')].length;
    msgs.push({when: tm ? tm[1] : '', sender: sender.slice(0, 28), out: isOut,
               text: body.slice(0, 320), media});
  }
  const unreadBadge = (() => {
    const h = document.querySelector('#main header [aria-label*="não lid"]');
    return h ? h.getAttribute('aria-label') : '';
  })();
  return JSON.stringify({header: hdr, rowTitle, unreadBadge, count: nodes.length, msgs});
})(%s, %s)
"""


def main() -> int:
    targets_file = sys.argv[1]
    tag = sys.argv[2] if len(sys.argv) > 2 else "1"
    n = int(sys.argv[3]) if len(sys.argv) > 3 else 10
    targets = json.load(open(targets_file, encoding="utf-8"))
    c = cdp.connect()
    out = []
    for t in targets:
        t0 = time.time()
        try:
            d = json.loads(c.eval(JS % (json.dumps(t["key"]), n)))
        except Exception as exc:  # noqa: BLE001
            d = {"error": f"{type(exc).__name__}: {str(exc)[:160]}"}
        d["_key"] = t["key"]
        d["_label"] = t["name"]
        d["_secs"] = round(time.time() - t0, 1)
        out.append(d)
        print(f"\n===== {t['name']} ({t['key']}) {d.get('_secs')}s =====")
        if d.get("error"):
            print("ERRO:", d["error"])
            continue
        print(f"header: {d['header']} | bolhas: {d['count']}")
        for m in d["msgs"]:
            flag = "->" if m["out"] else "<-"
            media = " [midia]" if m["media"] else ""
            print(f"  {flag} {m['when']:<20} {m['sender'][:22]:22} {m['text'][:130]}{media}")
    path = f"convos_{tag}.json"
    json.dump(out, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print(f"\nsalvo: {path}")
    return 0


if __name__ == "__main__":
    sys.exit(main())
