{"content": """"Abre uma aba nova no navegador Electron (porta 9222) e avalia JS nela.

Usa o endpoint browser-level (Target.createTarget) — o cdp.py padrão conecta
direto num target de página, o que serve para o WhatsApp mas não para abrir abas.
"""
import json
import time
import urllib.request

import cdp


def browser_ws(port=9222):
    return json.load(urllib.request.urlopen(f"http://127.0.0.1:{port}/json/version", timeout=10))[
        "webSocketDebuggerUrl"]


class Browser:
    def __init__(self, port=9222):
        self.port = port
        self.ws = cdp.WS(browser_ws(port))
        self._id = 0

    def call(self, method, **params):
        self._id += 1
        msg = json.dumps({"id": self._id, "method": method, "params": params})
        self.ws.send_text(msg)
        while True:
            res = json.loads(self.ws.recv_text())
            if res.get("id") == self._id:
                if "error" in res:
                    raise RuntimeError(f"{method}: {res['error']}")
                return res.get("result", {})

    def new_tab(self, url):
        return self.call("Target.createTarget", url=url)["targetId"]


def page_eval(url_needle, expression, timeout=25):
    """Conecta no target de página cujo URL contém url_needle e avalia a expressão."""
    deadline = time.time() + timeout
    while time.time() < deadline:
        t = cdp.find_target(needle=url_needle)
        if t:
            page = cdp.WS(t["webSocketDebuggerUrl"])
            msg = json.dumps({"id": 1, "method": "Runtime.evaluate",
                              "params": {"expression": expression, "returnByValue": True,
                                         "awaitPromise": True}})
            page.send_text(msg)
            while True:
                res = json.loads(page.recv_text())
                if res.get("id") == 1:
                    r = res.get("result", {}).get("result", {})
                    if "exceptionDetails" in res.get("result", {}):
                        raise RuntimeError(str(res["result"]["exceptionDetails"])[:400])
                    return r.get("value")
        time.sleep(0.8)
    raise TimeoutError(f"target não apareceu: {url_needle}")


if __name__ == "__main__":
    b = Browser()
    print("aba criada:", b.new_tab("https://trello.com/"))
    time.sleep(6)
    print(page_eval("trello.com", "document.title + ' | ' + location.href"))
