{"content": """"Navega a aba do navegador nativo (Electron, CDP 9222) para o Trello, lê o board e volta.

O Electron não cria aba nova, então a navegação acontece na aba existente. O estado do
WhatsApp é server-side, então voltar restaura a sessão.
"""
import json
import sys
import time

import cdp

WS = None


def page_ws():
    global WS
    if WS is None:
        t = cdp.find_target(needle="whatsapp.webor trello")
        WS = cdp.WS(t["webSocketDebuggerUrl"])
    return WS


def evaluate(expr, await_promise=True):
    ws = page_ws()
    ws.send_text(json.dumps({"id": 1, "method": "Runtime.evaluate",
                             "params": {"expression": expr, "returnByValue": True,
                                        "awaitPromise": await_promise}}))
    while True:
        res = json.loads(ws.recv_text())
        if res.get("id") == 1:
            r = res.get("result", {})
            if "exceptionDetails" in r:
                raise RuntimeError(json.dumps(r["exceptionDetails"])[:500])
            return r.get("result", {}).get("value")


def navigate(url, wait=6.0):
    ws = page_ws()
    ws.send_text(json.dumps({"id": 2, "method": "Page.navigate", "params": {"url": url}}))
    while True:
        res = json.loads(ws.recv_text())
        if res.get("id") == 2:
            break
    time.sleep(wait)
    return evaluate("location.href + ' | ' + document.title")


if __name__ == "__main__":
    print("antes:", evaluate("location.href"))
    print("agora:", navigate(sys.argv[1] if len(sys.argv) > 1 else "https://trello.com/"))
