{"content": """"Extrai cartões (nome, lista, prazo, etiquetas, link) de um board do Trello aberto no navegador.

Percorre o board na horizontal para materializar as listas virtualizadas e, em cada lista,
empurra o container de cartões para carregar os que estão fora da viewport.
"""
import json
import sys
import time

import nav_tab

JS_SCROLL = """
(async () => {
  const NL = String.fromCharCode(10);
  const board = document.querySelector('[data-testid="board"]') || document.scrollingElement;
  const seen = new Map();
  const name = el => (el?.innerText || el?.value || '').trim().split(NL)[0];
  const collect = () => {
    for (const li of document.querySelectorAll('li[data-testid="list-card"]')) {
      const a = li.querySelector('a[data-testid="card-name"]');
      if (!a) continue;
      const href = a.getAttribute('href') || '';
      if (seen.has(href)) continue;
      const list = li.closest('[data-testid="list"]');
      const due = list?.querySelector('[data-testid="due-date"], .card-due-date');
      const cardDue = li.querySelector('[data-testid="card-due"], .badge-text')?.innerText || '';
      seen.set(href, {
        name: (a.innerText || '').trim().replace(/\\s+/g, ' ').slice(0, 160),
        href, list: name(list?.querySelector('h2, [data-testid="list-header"]')),
        due: (cardDue || '').trim(),
        labels: [...li.querySelectorAll('[data-testid="compact-card-label"], [data-testid="card-label"]')]
                  .map(l => (l.getAttribute('title') || l.getAttribute('aria-label') || '').slice(0, 24))
                  .filter(Boolean).slice(0, 4),
        badges: [...li.querySelectorAll('[data-testid="card-badges"] *')].map(b => (b.innerText||'').trim()).filter(Boolean).slice(0,4)
      });
    }
  };
  // horizontal: percorre o board
  for (let pass = 0; pass < 2; pass++) {
    const max = board.scrollWidth || 0;
    for (let x = 0; x <= max; x += 700) {
      if (board.scrollTo) board.scrollTo({ left: x }); else board.scrollLeft = x;
      await new Promise(r => setTimeout(r, 220));
      collect();
      // vertical dentro das listas visíveis
      for (const list of document.querySelectorAll('[data-testid="list"]')) {
        const box = list.querySelector('[data-testid="list-cards"]') || list;
        if (!box || box.scrollHeight <= box.clientHeight + 10) continue;
        const top = box.scrollTop;
        box.scrollTop = box.scrollHeight;
        await new Promise(r => setTimeout(r, 180));
        collect();
        box.scrollTop = top;
      }
    }
    if (board.scrollTo) board.scrollTo({ left: 0 });
  }
  return JSON.stringify([...seen.values()]);
})()
"""

if __name__ == "__main__":
    url, slug = sys.argv[1], sys.argv[2]
    print(nav_tab.navigate(url, wait=8))
    cards = json.loads(nav_tab.evaluate(JS_SCROLL))
    json.dump(cards, open(f"trello_{slug}.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    by_list = {}
    for c in cards:
        by_list.setdefault(c["list"], []).append(c)
    print(f"{slug}: {len(cards)} cartões em {len(by_list)} listas")
    for lst, items in by_list.items():
        done = any(k in (lst or "").lower() for k in ("finaliz", "conclu", "done"))
        print(f"  {'[FECHADA] ' if done else ''}{lst} -> {len(items)}")
