{"content": """"Primitivas de WhatsApp Web via CDP (stdlib + cdp.py local).

Lições de 23/10: a lista virtualiza (só ~16 linhas no DOM), as linhas são
`[data-testid^="list-item-"]` (não role=listitem), e a busca é um `<input>` React
que só aceita valor pelo setter nativo — Input.insertText concatena no texto antigo.
"""
from __future__ import annotations

import json
import time

import cdp

SEL_BUSCA = '[data-testid="chat-list-search-container"] input'
SEL_LINHAS = '#pane-side [data-testid^="list-item-"]'
SEL_HEADER = "#main header"
SEL_COMPOSER = '#main footer div[contenteditable="true"]'

_SET = ("(() => { const i=document.querySelector(%s); if(!i) return null;"
        " const s=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;"
        " s.call(i, %s); i.dispatchEvent(new Event('input',{bubbles:true})); return i.value })()")


def conectar() -> "cdp.CDP":
    return cdp.connect()


def _js(c, expr):
    return c.eval(expr)


def texto(c, seletor: str) -> str:
    return _js(c, f"(document.querySelector({json.dumps(seletor)})||{{}}).innerText || ''") or ""


def linhas(c) -> list[str]:
    expr = ("(JSON.stringify([...document.querySelectorAll(%s)]"
            ".map(r => (r.innerText||'').replace(/[\\s]+/g,' ').trim().slice(0,90))))"
            % json.dumps(SEL_LINHAS))
    return json.loads(_js(c, expr) or "[]")


def buscar(c, termo: str, pausa: float = 2.2) -> list[str]:
    _js(c, _SET % (json.dumps(SEL_BUSCA), json.dumps(termo)))
    time.sleep(pausa)
    return linhas(c)


def limpar_busca(c, pausa: float = 1.2) -> None:
    _js(c, _SET % (json.dumps(SEL_BUSCA), json.dumps("")))
    time.sleep(pausa)


def abrir(c, termo: str, esperado: str | None = None, pausa: float = 2.5) -> str:
    """Busca, clica na conversa certa e valida o cabeçalho. Devolve o cabeçalho."""
    itens = buscar(c, termo)
    alvo = None
    for i, t in enumerate(itens):
        if esperado and esperado.lower() in t.lower():
            alvo = i
            break
    if alvo is None and not esperado and itens:
        alvo = 0
    if alvo is None:
        raise RuntimeError(f"nenhuma conversa casou com {termo!r}: {itens[:6]}")
    clicar(c, alvo, pausa)
    hdr = texto(c, SEL_HEADER).split("\n")[0].strip()
    if esperado and esperado.lower() not in hdr.lower():
        raise RuntimeError(f"cabeçalho inesperado: abriu {hdr!r}, esperava {esperado!r}")
    return hdr


def clicar(c, indice: int, pausa: float = 2.5) -> None:
    expr = ("(() => { const r=document.querySelectorAll(%s)[%d]; if(!r) return false;"
            " r.dispatchEvent(new MouseEvent('mousedown',{bubbles:true})); r.click(); return true })()"
            % (json.dumps(SEL_LINHAS), indice))
    if not _js(c, expr):
        raise RuntimeError(f"linha {indice} não existe")
    time.sleep(pausa)


def bolhas(c, limite: int = 40) -> list[dict]:
    expr = ("(JSON.stringify([...document.querySelectorAll('#main [data-id]')].slice(-%d).map(m => ({"
            "o: !!m.querySelector('.message-out'),"
            "t: (m.innerText||'').replace(/[\\s]+/g,' ').slice(0,260),"
            "h: (m.querySelector('[data-pre-plain-text]')||{}).getAttribute ?"
            " (m.querySelector('[data-pre-plain-text]')||{}).getAttribute('data-pre-plain-text') : ''"
            "}))))" % limite)
    return json.loads(_js(c, expr) or "[]")


def enviar(c, mensagem: str, pausa: float = 1.6) -> None:
    ok = _js(c, f"(() => {{ const e=document.querySelector({json.dumps(SEL_COMPOSER)});"
                " if(!e) return false; e.focus(); return true })()")
    if not ok:
        raise RuntimeError("caixa de mensagem não encontrada")
    c.call("Input.insertText", text=mensagem)
    time.sleep(0.7)
    for tipo in ("keyDown", "keyUp"):
        c.call("Input.dispatchKeyEvent", type=tipo, key="Enter", code="Enter",
               windowsVirtualKeyCode=13, nativeVirtualKeyCode=13)
    time.sleep(pausa)


def estado(c) -> dict:
    return json.loads(_js(c, "JSON.stringify({url: location.href,"
                             " pane: !!document.querySelector('#pane-side'),"
                             " main: !!document.querySelector('#main'),"
                             " qr: [...document.querySelectorAll('canvas')].length})"))
