{"content": """"Encaminha (nativo) a imagem de divulgação do Hackatur, que está em Imprensa Sudoexpo, para os chats pedidos."""
from __future__ import annotations

import json
import sys
import time

import wa2 as wa

ORIGEM = ("Imprensa Sudoexpo", "Imprensa")


def cdp_js(c, expr, arg=None):
    return c.eval("(function(a){var d=document.querySelector('div[role=dialog]'); %s})(%s)" % (expr, json.dumps(arg)))


def abrir_encaminhar(c) -> bool:
    wa.abrir(c, ORIGEM[0], ORIGEM[1], pausa=2)
    info = json.loads(c.eval("""(function(){var b=[].slice.call(document.querySelectorAll('#main [data-id]'))
        .filter(function(m){return m.querySelector('img[src^="blob"]')}).pop();
        if(!b) return 'null';
        var p=b.parentElement; while(p && p!==document.body && !(p.scrollHeight>p.clientHeight+20)) p=p.parentElement;
        if(p) p.scrollTop=p.scrollHeight;
        var r=b.getBoundingClientRect(); return JSON.stringify({x:r.x+r.width/2,y:r.y+r.height/2})})()"""))
    if info == 'null':
        return False
    time.sleep(0.8)
    c.call('Input.dispatchMouseEvent', type='mouseMoved', x=info['x'], y=info['y'])
    time.sleep(1.2)
    btn = c.eval("""(function(){var el=[].slice.call(document.querySelectorAll('[aria-label="Encaminhar mídia"]')).pop();
        if(!el) return 'null'; var r=el.getBoundingClientRect();
        return JSON.stringify({x:r.x+r.width/2,y:r.y+r.height/2})})()""")
    if btn == 'null':
        return False
    b = json.loads(btn)
    c.call('Input.dispatchMouseEvent', type='mousePressed', x=b['x'], y=b['y'], button='left', clickCount=1)
    c.call('Input.dispatchMouseEvent', type='mouseReleased', x=b['x'], y=b['y'], button='left', clickCount=1)
    time.sleep(2.0)
    return c.eval("!!document.querySelector('div[role=dialog]')") is True


def escolher(c, nome: str) -> bool:
    cdp_js(c, "var i=d.querySelector('input[type=text]');"
              "var set=Object.getOwnPropertyDescriptor(HTMLInputElement.prototype,'value').set;"
              "set.call(i,a); i.dispatchEvent(new Event('input',{bubbles:true})); return true", nome)
    time.sleep(1.8)
    pos = cdp_js(c, "var rows=[].slice.call(d.querySelectorAll('[role=listitem], li'));"
                    "for(var k=0;k<rows.length;k++){var t=(rows[k].innerText||'').replace(/\\s+/g,' ').trim();"
                    "if(t.indexOf(a)===0){var b=rows[k].getBoundingClientRect();"
                    "return JSON.stringify({x:b.x+8,y:b.y+8,t:t.slice(0,40)})}} return 'null'", nome)
    if pos == 'null':
        return False
    o = json.loads(pos)
    print('   linha:', o['t'])
    c.call('Input.dispatchMouseEvent', type='mousePressed', x=o['x'], y=o['y'], button='left', clickCount=1)
    c.call('Input.dispatchMouseEvent', type='mouseReleased', x=o['x'], y=o['y'], button='left', clickCount=1)
    time.sleep(1.5)
    return True


def enviar(c) -> bool:
    pos = cdp_js(c, "var e=d.querySelector('[aria-label=\"Enviar\"]'); if(!e) return 'null';"
                    "var b=e.getBoundingClientRect(); return JSON.stringify({x:b.x+b.width/2,y:b.y+b.height/2})")
    if pos == 'null':
        return False
    o = json.loads(pos)
    c.call('Input.dispatchMouseEvent', type='mousePressed', x=o['x'], y=o['y'], button='left', clickCount=1)
    c.call('Input.dispatchMouseEvent', type='mouseReleased', x=o['x'], y=o['y'], button='left', clickCount=1)
    time.sleep(2.5)
    return not c.eval("!!document.querySelector('div[role=dialog]')")


def main(alvos: list[tuple[str, str]]) -> int:
    c = wa.conectar()
    for nome, esperado in alvos:
        print(f'\n>> {nome}')
        if not abrir_encaminhar(c):
            print('   falhou ao abrir o encaminhamento'); continue
        if not escolher(c, nome):
            print('   destino não encontrado na lista'); continue
        print('   enviado:', enviar(c))
    return 0


if __name__ == "__main__":
    raise SystemExit(main([
        ("DIRETORIA ACIRV - TRIENIO 2025/2028", "DIRETORIA"),
        ("Grupo de RH de Rio Verde", "RH de Rio"),
    ]))
